import createTree from '@pablo-mayrgundter/yaot2'
import {assertDefined} from '../assert'
import {queryPoints} from './Picker'
import SpriteSheet from './SpriteSheet.js'
import {marker as createMarker} from './shapes'
import {rteCameraLocal} from './rte.js'
import {overlay} from '../shared.js'


const HOVER_SYNC_MS = 80


/** */
export default class PickLabels {
  constructor(ui, stars) {
    assertDefined(ui, stars)
    this.ui = ui
    this.stars = stars
    this.pickedStarLabels = {}
    this.marker = null
    this.tree = null
    this.traceLabel = null
    this.mcb = null
    this.tcb = null
    this._searchSyncTimer = null
    this._pendingHoverName = null

    // Activate when UI button clicked for star marking.
    // Use prevState comparison so we only act when this flag actually changes,
    // not on every unrelated store update (which would pile up markers/listeners).
    this.ui.useStore.subscribe((state, prevState) => {
      if (state.isStarsSelectActive === prevState.isStarsSelectActive) {
        return
      }
      if (state.isStarsSelectActive) {
        this.addPickListeners()
      } else {
        this.removePickListeners()
        this.clearTrace()
        this._clearHoverSync()
      }
    })
  }

  /**
   * The spatial index over the stars loaded so far: built on first use,
   * and again when the catalogue's tiers have brought more (Stars.md,
   * "Brightness tiers"), so a faint star can be picked once its tier is in.
   *
   * @returns {{tree: object, index: object}}
   */
  _index() {
    const index = this.stars.pickIndex()
    if (!this.tree || this._treeVersion !== index.version) {
      this.tree = createTree()
      this.tree.init(index.coords)
      this._treeVersion = index.version
    }
    return {tree: this.tree, index}
  }


  /** Add dblclick calls mark, mousemove calls trace */
  addPickListeners() {
    this._index()
    this.marker = overlay(createMarker())
    this.ui.scene.add(this.marker)
    const me = this
    this.mcb = (e) => me.markCb(e)
    this.tcb = (e) => me.traceCb(e)
    document.body.addEventListener('dblclick', this.mcb)
    document.body.addEventListener('mousemove', this.tcb)
  }

  /** Remove dblclick and mousemove listeners */
  removePickListeners() {
    document.body.removeEventListener('dblclick', this.mcb)
    document.body.removeEventListener('mousemove', this.tcb)
    this.ui.scene.remove(this.marker)
  }

  /** Mark and label current star */
  traceCb(e) {
    const {tree, index} = this._index()
    queryPoints(this.ui, e, tree, this.stars, (pick) => {
      // pick.x/y/z are catalog coords; marker lives in world space.
      this.marker.position.set(pick.x, pick.y, pick.z)
      this.stars.localToWorld(this.marker.position)
      this.clearTrace()
      const name = this.stars.catalog.getNameOrId(pick.star.hipId)
      if (!this.stars.labelCenterPosByName[name]) {
        this.traceLabel = this.labelStar(pick)
      }
      this._queueHoverSync(`${name}`)
    }, index)
  }


  /**
   * Debounced pipe from mousemove-hover to store.searchHoverName.  mousemove
   * fires ~60–120 Hz; 80 ms coalesces into a rate the SearchBar can react to
   * without thrashing Fuse.
   *
   * @param {string} name
   */
  _queueHoverSync(name) {
    this._pendingHoverName = name
    if (this._searchSyncTimer) {
      return
    }
    this._searchSyncTimer = setTimeout(() => {
      this._searchSyncTimer = null
      const store = this.ui.useStore
      if (store && typeof store.getState === 'function') {
        const setter = store.getState().setSearchHoverName
        if (typeof setter === 'function') {
          setter(this._pendingHoverName)
        }
      }
    }, HOVER_SYNC_MS)
  }


  _clearHoverSync() {
    if (this._searchSyncTimer) {
      clearTimeout(this._searchSyncTimer)
      this._searchSyncTimer = null
    }
    this._pendingHoverName = null
    const store = this.ui.useStore
    if (store && typeof store.getState === 'function') {
      const setter = store.getState().setSearchHoverName
      if (typeof setter === 'function') {
        setter(null)
      }
    }
  }

  /** Leave a label on star and navigate there */
  markCb(e) {
    const {tree, index} = this._index()
    queryPoints(this.ui, e, tree, this.stars, (pick) => {
      this.pickedStarLabels[pick.star.hipId] = this.traceLabel
      this.traceLabel = null
      // Goes, and targets the star (Scene.setTarget).
      this.ui.sceneManager.goTo(pick.star, String(this.stars.catalog.getNameOrId(pick.star.hipId)))
      const store = this.ui.useStore
      if (store && typeof store.getState === 'function') {
        const state = store.getState()
        // Resolve the search: dblclick commits just like Enter/Go would.
        // closeSearch also deactivates picking mode, which removes these
        // listeners — clean end to the interaction.
        if (state.isSearchOpen && typeof state.closeSearch === 'function') {
          state.closeSearch()
        }
      }
    }, index)
  }

  /** If there's a current trace label, remove it from scene */
  clearTrace() {
    if (this.traceLabel) {
      this.traceLabel.removeFromParent()
    }
  }

  /**
   * Add star's name as label at its position
   *
   * @returns {object} The label
   */
  labelStar(pick) {
    const starName = `${this.stars.catalog.getNameOrId(pick.star.hipId)}`
    const labelSheet = new SpriteSheet(1, starName, undefined, [0, 1e5], true)
    // Use pick.star.xyz (float32_LY * LIGHTYEAR_METER) so SpriteSheet's high/low
    // split produces the same positionLow as StarsBufferGeometry — without this,
    // Math.fround(pick.x) === pick.x so positionLow=0 and the label jumps each
    // time the camera's float32 camHigh steps by one ULP (~5e11 m).
    labelSheet.add(pick.star.x, pick.star.y, pick.star.z, starName)
    const label = overlay(labelSheet.compile())
    label.onBeforeRender = (renderer, scene, camera) => {
      const u = label.material.uniforms
      rteCameraLocal(label, camera, u.uCamPosWorldHigh.value, u.uCamPosWorldLow.value)
    }
    // In the stars' frame, like the catalogue labels: the position is J2000.
    this.stars.add(label)
    return label
  }
}
